import os,pty,fcntl,termios,struct,subprocess,select,pathlib
lab=pathlib.Path(__file__).parent
master,slave=pty.openpty()
fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',44,140,0,0))
def childsetup():
 os.setsid()
 fcntl.ioctl(0,termios.TIOCSCTTY,0)
p=subprocess.Popen([str(lab/'zellij'),'--session',os.environ['FM_ZELLIJ_SESSION'],'--new-session-with-layout',str(lab/'layout.kdl')],cwd=lab,env=os.environ,stdin=slave,stdout=slave,stderr=slave,preexec_fn=childsetup)
os.close(slave)
(lab/'client.pid').write_text(str(p.pid))
with open(os.environ['ZELLIJ_EVIDENCE']+'/zellij-client-b.ansi','wb') as out:
 try:
  while p.poll() is None and not (lab/'stop').exists():
   if select.select([master],[],[],0.2)[0]:
    try:data=os.read(master,65536)
    except OSError:break
    if not data:break
    out.write(data);out.flush()
 finally:
  if p.poll() is None:
   p.terminate()
   try:p.wait(timeout=5)
   except subprocess.TimeoutExpired:p.kill();p.wait()
  os.close(master)
